"""Build the Task 3 PDF and Markdown report from actual run artifacts."""
from __future__ import annotations
import json
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, KeepTogether
from src.utils import ROOT
from src.visualization import slug

def generate(root: Path = ROOT):
    results = json.loads((root/"outputs/evaluation_results.json").read_text(encoding="utf-8"))
    rows = results["results"]
    out_md = root/"reports/Model_Evaluation_Report.md"
    lines = ["# Employee Attrition Model Evaluation Report", "", "## Objective and methodology", "This report compares four baseline classifiers and a GridSearchCV-tuned Random Forest on the IBM HR Analytics employee dataset. Task 2's fixed stratified 80/20 split (seed 42) is reused. All preprocessing is cloned and fitted within each training fold during cross-validation, then fitted on the full training partition for final test evaluation. The target `Attrition` is never included in model features.", "", "## Dataset and target", "The packaged Task 2 cleaned dataset contains 1,470 employee rows and 37 columns, with `Attrition` as the binary target (`No`/`Yes`; Yes is positive). The fixed split contains 1,176 training rows and 294 held-out test rows; test class counts are 247 No and 47 Yes. Task 2 quality checks found zero missing cells and zero exact duplicate rows.", "", "## Algorithms and settings", "The four baselines are Logistic Regression (balanced class weight, 2,000 iteration cap), Decision Tree (balanced class weight, minimum leaf size 3), Random Forest (200 trees, balanced subsampling, minimum leaf size 2), and K-Nearest Neighbors (7 neighbors, distance weighting). The tuned Random Forest uses 5-fold stratified GridSearchCV and positive-class F1 scoring across 12 candidates: n_estimators 100/200, max_depth 5/10/None, and min_samples_split 2/5.", "", "## Held-out test comparison", "All values below are measured on the same held-out Task 2 test set. Precision, recall and F1 refer to Attrition=Yes.", "", "| Candidate | Accuracy | Precision | Recall | F1 | ROC-AUC |", "|---|---:|---:|---:|---:|---:|"]
    for r in rows: lines.append(f"| {r['model']} | {r['accuracy']:.3f} | {r['precision']:.3f} | {r['recall']:.3f} | {r['f1']:.3f} | {r['roc_auc']:.3f} |")
    lines += ["", f"## Grid search and model selection", f"Training-only cross-validation selected `{results['cv']['best_params']}` with mean CV F1 {results['cv']['best_mean_cv_f1']:.3f}. The candidate is selected exclusively by highest mean positive-class F1 from training-only stratified cross-validation (the tuned RF uses its GridSearchCV CV score). The selected candidate is **{results['winner']}**. The fixed test partition is reserved for final evaluation only.", "", "## Interpretation and business trade-offs", "The target is imbalanced (only 47 of 294 test employees are labeled Yes). Accuracy can therefore hide missed attrition cases. Higher recall catches more potential leavers but may create more false positives and unnecessary outreach; higher precision reduces unnecessary interventions but can miss employees needing support. Confusion matrices and ROC curves provide complementary views. ROC-AUC measures ranking over thresholds and does not identify a practical operating threshold. Correlation and feature importance do not establish causation.", "", "## Limitations, responsible use, and privacy", "This dataset is a historical, synthetic-style HR analytics benchmark distributed for research/education, not a representative causal study of a particular employer. The small positive class, potential historical bias, proxy variables, and distribution shift limit generalization. Attrition predictions must be decision-support signals only; never use them for punitive decisions or automated employment actions. Restrict access to personal data, minimize retention, assess subgroup error rates and disparate impact, obtain human review, and provide fair support independent of the score.", "", "## Reproducibility and model persistence", f"Random seed 42 and the Task 2 split manifest are used. The selected estimator is a Pipeline containing preprocessing and classifier. It was saved and reloaded; reloaded predictions matched the fitted pipeline on all {results['task2_split']['test_rows']} test records, and {results['unseen_rows_verified']} compatible unseen rows (including an unknown JobRole) transformed and predicted successfully.", "", "## Charts", "Confusion matrices are provided for each candidate, with a shared held-out ROC plot and feature importance when supported. See the accompanying image files and captions in the PDF.", "", "## References", "- IBM HR Analytics Employee Attrition & Performance dataset, IBM sample dataset commonly distributed via Kaggle: https://www.kaggle.com/datasets/pavansubhasht/ibm-hr-analytics-attrition-dataset (dataset attribution; see Task 2 provenance).", "- Scikit-learn documentation: Pipeline, ColumnTransformer, GridSearchCV, classification metrics.", ""]
    out_md.write_text("\n".join(lines), encoding="utf-8")
    pdf = root/"reports/Model_Evaluation_Report.pdf"
    doc = SimpleDocTemplate(str(pdf), pagesize=letter, rightMargin=0.62*inch,leftMargin=0.62*inch,topMargin=.65*inch,bottomMargin=.62*inch,title="Employee Attrition Model Evaluation Report",author="AI/ML Internship Task 3")
    styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name="ReportTitle", parent=styles["Title"], alignment=TA_CENTER, textColor=colors.HexColor("#263B70"), spaceAfter=14)); styles.add(ParagraphStyle(name="Small",parent=styles["BodyText"],fontSize=8,leading=10))
    story=[Paragraph("Employee Attrition Model Evaluation",styles["ReportTitle"]),Paragraph("AI/ML Internship Task 3 | Model training, evaluation, and responsible-use review",styles["Heading2"]),Spacer(1,12)]
    for section, text in [("Objective and methodology", lines[3]), ("Dataset and target", lines[5] if not lines[5].startswith("##") else "The cleaned Task 2 dataset has 1,470 rows and 37 columns; Attrition is the Yes/No target and Yes is positive. The fixed 80/20 split has 1,176 training and 294 test records (247 No, 47 Yes); Task 2 quality checks found no missing cells or exact duplicates."), ("Algorithms and settings", lines[7] if not lines[7].startswith("##") else "Logistic Regression, Decision Tree, Random Forest and KNN were trained with documented class-imbalance settings. GridSearchCV evaluated 12 Random Forest parameter combinations using 5-fold stratified training-only CV and positive-class F1.")]:
        story += [Paragraph(section,styles["Heading1"]),Paragraph(text.replace("`",""),styles["BodyText"]),Spacer(1,8)]
    story += [Paragraph("Held-out test comparison",styles["Heading1"]),Paragraph("Positive-class metrics use Attrition=Yes. Test set: 294 records; 47 positive.",styles["BodyText"]),Spacer(1,8)]
    table_data=[["Candidate","Accuracy","Precision","Recall","F1","ROC-AUC"]]+[[r["model"],*[f"{r[k]:.3f}" for k in ("accuracy","precision","recall","f1","roc_auc")]] for r in rows]
    t=Table(table_data, repeatRows=1, colWidths=[2.2*inch,.75*inch,.75*inch,.65*inch,.55*inch,.7*inch]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#263B70")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#C8CEDA")),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F1F4FA")]),("FONTSIZE",(0,0),(-1,-1),8),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),5),("RIGHTPADDING",(0,0),(-1,-1),5)])); story += [t,Spacer(1,12)]
    story += [Paragraph("Grid search and model selection",styles["Heading1"]),Paragraph(f"5-fold stratified GridSearchCV used F1 scoring on training data only. Best parameters: {results['cv']['best_params']}; mean CV F1: {results['cv']['best_mean_cv_f1']:.3f}. Selected candidate: {results['winner']} by training-only mean CV F1. The held-out comparison is evaluation-only and did not participate in candidate selection.",styles["BodyText"]),Spacer(1,8),Paragraph("Business interpretation",styles["Heading1"]),Paragraph("The target is imbalanced. Accuracy alone can conceal missed attrition cases. Higher recall may identify more employees for supportive conversations but can also create false alarms; higher precision lowers unnecessary outreach but can miss employees needing support. ROC-AUC summarizes ranking across thresholds; it is not a deployment threshold. Correlation and feature importance are not causal evidence.",styles["BodyText"]),Spacer(1,8)]
    story += [PageBreak()]
    for heading, body in [("Responsible use and limitations","The data is a benchmark, not a causal or employer-specific study. Small positive class, historical bias, proxy features, and distribution shift limit generalization. Never use scores for punitive or automated employment decisions. Minimize data access and retention; assess subgroup error rates and disparate impact; use human review and offer fair support independently of a score."),("Reproducibility and persistence",f"Random seed 42; Task 2 fixed split reused (1,176 train / 294 test). Preprocessing is inside the serialized sklearn Pipeline and never fit on test data. Saved model reloaded with identical predictions on all {results['task2_split']['test_rows']} test rows; {results['unseen_rows_verified']} unseen compatible rows including an unknown JobRole were accepted.")]:
        story += [Paragraph(heading,styles["Heading1"]),Paragraph(body,styles["BodyText"]),Spacer(1,8)]
    for title, image_name, caption in [("ROC curves","roc_curves.png","Figure 1. ROC curves generated from held-out test probabilities."),("Feature importance","feature_importance.png","Figure 2. Top impurity-based feature importances for the tuned Random Forest; this is not causal evidence.")]:
        image=root/"images"/image_name
        if image.exists():
            story += [PageBreak(),Paragraph(title,styles["Heading1"]),Image(str(image),width=6.7*inch,height=4.6*inch,kind="proportional"),Paragraph(caption,styles["Small"])]
    for result in rows:
        image=root/"images"/f"confusion_matrix_{result['model'].lower().replace(' ','_').replace('(','').replace(')','').replace('-','_')}.png"
        # Match chart slug generation without relying on a hard-coded model subset.
        import re
        image=root/"images"/("confusion_matrix_"+slug(result["model"])+".png")
        if image.exists():
            story += [PageBreak(),Paragraph(f"Confusion matrix: {result['model']}",styles["Heading1"]),Image(str(image),width=5.7*inch,height=4.7*inch,kind="proportional"),Paragraph("Figure. Rows are actual labels; columns are predicted labels. Attrition=Yes is the positive class.",styles["Small"])]
    story += [Spacer(1,12),Paragraph("References",styles["Heading1"]),Paragraph("IBM HR Analytics Employee Attrition & Performance dataset (educational benchmark); https://www.kaggle.com/datasets/pavansubhasht/ibm-hr-analytics-attrition-dataset. Scikit-learn user guide: Pipeline, ColumnTransformer, GridSearchCV, model evaluation.",styles["BodyText"])]
    doc.build(story)
    return pdf
if __name__ == "__main__": print(generate())
